export interface KindredFigure {
  name: string;
  note: string;
  entryId?: string;
}

export interface KindredFigureGroup {
  title?: string;
  figures: KindredFigure[];
}

export type KindredBlock =
  | { kind: "p"; text: string }
  | { kind: "h"; text: string }
  | { kind: "ul"; items: string[] };

export interface KindredSourceBook {
  title: string;
  lead?: string;
  items: string[];
}

export interface KindredSourceGroup {
  title: string;
  books: KindredSourceBook[];
}

export interface KindredObservations {
  heading: string;
  intro?: string;
  items: string[];
}

export interface KindredSources {
  heading?: string;
  intro?: string;
  items?: string[];
  groups?: KindredSourceGroup[];
  observations?: KindredObservations;
  note?: string;
}

export interface Kindred {
  id: string;
  name: string;
  image: string;
  alt: string;
  about: string;
  title?: string;
  paragraphs?: string[];
  blocks?: KindredBlock[];
  figuresLead?: KindredBlock[];
  figureGroups?: KindredFigureGroup[];
  sources?: KindredSources;
  figures: KindredFigure[];
}

export function kindredImageSrc(file: string) {
  return `/criaturas-raca/${encodeURIComponent(file)}`;
}

